-- Load the Athena vocabulary CSVs (tab-separated, UTF-8, header row) with
-- BULK INSERT. Generated by tools/make-vocab-load.py; do not edit by hand.
-- sqlcmd variables: CDM_SCHEMA, VOCAB_DIR and FMT_DIR (paths in the container).

PRINT CONCAT(CONVERT(varchar(19), SYSDATETIME(), 120), ' loading VOCABULARY');
TRUNCATE TABLE $(CDM_SCHEMA).VOCABULARY;
BULK INSERT $(CDM_SCHEMA).VOCABULARY FROM '$(VOCAB_DIR)/VOCABULARY.csv'
  WITH (FORMATFILE = '$(FMT_DIR)/VOCABULARY.xml', FIRSTROW = 2, TABLOCK, BATCHSIZE = 500000, MAXERRORS = 0);
SELECT 'VOCABULARY' AS loaded, COUNT_BIG(*) AS row_count FROM $(CDM_SCHEMA).VOCABULARY;
GO

